/** Additional samples exercise native codecs and typed text runs through the public API. */
export function createAssetScenes(S){
 const run=draw=>(canvas,w,h)=>{const held=[],own=v=>(held.push(v),v),paint=(color,size=0)=>own(new S.SKPaint({Color:S.SKColor.Parse(color),Style:size?S.SKPaintStyle.Stroke:S.SKPaintStyle.Fill,StrokeWidth:size,IsAntialias:true})),font=size=>own(new S.SKFont(null,size)),label=(text,x,y,size=20,color='#D8E9F4')=>canvas.DrawText(text,x,y,font(size),paint(color));const save=canvas.Save();try{canvas.Scale(w/960,h/600);draw(canvas,{own,paint,font,label});}finally{canvas.RestoreToCount(save);held.reverse().forEach(v=>v?.Dispose());}};
 return[
 {id:'native_asset_codecs',group:'Images & pixels',title:'Native codecs & pixel views',tag:'PNG filters · JPEG chroma · WebP lossless',description:'Encode a shared bitmap through the native encoders, decode it, and inspect the resulting byte sizes.',code:'const pixmap = bitmap.PeekPixels();\nconst png = pixmap.Encode(new SKPngEncoderOptions(\n  SKPngEncoderFilterFlags.AllFilters, 9));\nconst jpeg = pixmap.Encode(new SKJpegEncoderOptions(\n  92, SKJpegEncoderDownsample.Downsample444,\n  SKJpegEncoderAlphaOption.Ignore));\nconst webp = pixmap.Encode(new SKWebpEncoderOptions(\n  SKWebpEncoderCompression.Lossless, 75));',draw:run((c,{own,paint,label})=>{label('One bitmap. Three native encoders.',48,85,36);const bitmap=own(new S.SKBitmap(96,96));const pixels=bitmap.GetPixelSpan();for(let y=0;y<96;y++)for(let x=0;x<96;x++){const i=(y*96+x)*4;pixels[i]=Math.round(x*255/95);pixels[i+1]=Math.round(y*255/95);pixels[i+2]=((x>>3)^(y>>3))&1?230:40;pixels[i+3]=255;}bitmap.NotifyPixelsChanged();const pixmap=own(bitmap.PeekPixels()),formats=[['PNG · adaptive filters',new S.SKPngEncoderOptions(248,9)],['JPEG · chroma 4:4:4',new S.SKJpegEncoderOptions(92,'Downsample444','Ignore')],['WebP · lossless',new S.SKWebpEncoderOptions('Lossless',75)]];formats.forEach(([title,opts],i)=>{const data=own(pixmap.Encode(opts)),image=own(S.SKImage.FromEncodedData(data)),x=48+i*304;c.DrawImage(image,S.SKRect.Create(x,155,255,255),paint('#FFFFFF'));label(title,x,450,18);label(data.Size.toLocaleString()+' bytes',x,486,23,'#30DEAB');});label('Subset views share storage; encoder outputs own their byte buffers.',48,555,20);})},
 {id:'typed_text_runs',group:'Text & fonts',title:'Typed text runs & clusters',tag:'SKTextBlobBuilder · UTF-8 · Intercepts',description:'Build glyph runs with explicit positions, original UTF-8 text and byte clusters; inspect native text intercepts.',code:'const builder = new SKTextBlobBuilder();\nconst run = builder.AllocatePositionedTextRun(font, 5, 5);\nrun.SetGlyphs(font.GetGlyphs("Hello"));\nrun.SetPositions(positions);\nrun.SetText(new TextEncoder().encode("Hello"));\nrun.SetClusters([0, 1, 2, 3, 4]);\nconst blob = builder.Build();\nconst intervals = blob.GetIntercepts(245, 285);',draw:run((c,{own,paint,font,label})=>{label('Text has geometry. Text has meaning.',48,85,35);const f=font(105),builder=own(new S.SKTextBlobBuilder()),glyphs=f.GetGlyphs('Hello'),positions=f.GetGlyphPositions(glyphs,new S.SKPoint(60,300)),run=builder.AllocatePositionedTextRun(f,glyphs.length,5);run.SetGlyphs(glyphs);run.SetPositions(positions);run.SetText(new TextEncoder().encode('Hello'));run.SetClusters([0,1,2,3,4]);const blob=own(builder.Build());c.DrawRect(S.SKRect.Create(48,245,860,40),paint('#203445'));c.DrawTextBlob(blob,0,0,paint('#D8E9F4'));const intervals=blob.GetIntercepts(245,285);for(let i=0;i<intervals.length;i+=2)c.DrawLine(intervals[i],330,intervals[i+1],330,paint('#30DEAB',6));label('Native outline intervals inside the highlighted band',48,402,22);label('UTF-8 bytes: 48 65 6C 6C 6F',48,465,19,'#A8B4C5');label('Clusters: 0 · 1 · 2 · 3 · 4',48,500,19,'#A8B4C5');label('Document exports can retain the original text and glyph placement.',48,555,20);})}
 ];
}
